/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Timeline
 *   Functions: lookup, running, show, items, rows, notes, only
 *   Constants: startedAt, searches, titles
 * Tests
 *   - while a run is active its steps read in order with what each searched, their states and counts, without a live region
 *   - a running run that shows no new step for more than five seconds of this page's clock says it waits for MusicBrainz, iTunes in the iTunes phase, and a queued or retrying run never does
 *   - after a run it says what it searched, then folds its steps under the record with the time taken, searches and releases
 *   - a stopped run folds its record without the names searched, and the steps it never reached read as not run
 *   - a search the run may not have sent reads as such, and is neither named as searched nor counted
 *   - a run that completed after MusicBrainz's retries ran out names no search, as it may not have sent them
 *   - each Track-title state reads in its own words: sent with its titles, not needed, not yet, and every skip reason
 *   - the iTunes fallback reads as not needed or unavailable, or says only some of its results were compared, and the bridge names the titles it checked and why they were found; a search the candidate bound kept unsent is skipped
 *   - a search whose text is not shown reads as a search by name, and a song search names its song
 *   - a run ended because its Album changed offers opening the Album, with or without a timeline
 *   - a view without a timeline renders nothing
 * @end-catalog */

import { cleanup, render, screen, within } from '@testing-library/react';
import { MemoryRouter } from 'react-router';
import type { ReviewLookupView } from './importLookupApi';
import { pairingLookupResponse, pairingRunningTimeline, pairingTimeline } from './catalogReviewLookupFixtures.testSupport';
import { LookupProgress } from './LookupProgress';

/**
 * The review lookup's step list on its own: the steps in order with what each searched, their states and counts, the wait for a
 * source, the names searched and the folded record after a run, each Track-title and iTunes state in its own words, and the link
 * to open an Album that changed. All names and identifiers are synthetic.
 */
type Timeline = NonNullable<ReviewLookupView['timeline']>;
const startedAt = '2026-10-22T01:24:52.000Z';
const lookup = (extra: Partial<ReviewLookupView> = {}): ReviewLookupView => ({ ...pairingLookupResponse().lookup!, timeline: pairingTimeline(), ...extra });
const running = (updatedAt: string, extra: Partial<ReviewLookupView> = {}) => lookup({ state: 'running', outcome: null, timeline: pairingRunningTimeline(updatedAt),
  progress: { phase: 'details', done: 5, total: 12, startedAt, updatedAt }, ...extra });
const show = (view: ReviewLookupView, now = Date.parse('2026-10-22T01:25:30.000Z'), albumHref: string | null = null) =>
  render(<MemoryRouter><LookupProgress lookup={view} now={now} albumHref={albumHref} /></MemoryRouter>);
const items = () => within(screen.getByRole('list', { name: 'Lookup steps' })).getAllByRole('listitem');
/** Each row's own words, and the line a row adds below them (empty when it adds none). */
const rows = () => items().map(item => item.firstChild!.textContent);
const notes = () => items().map(item => item.childNodes[1]?.textContent ?? '');
/** A completed run whose steps are only the Track-title and iTunes rows given. */
const only = (steps: Timeline['steps'], extra: Partial<Timeline> = {}, view: Partial<ReviewLookupView> = {}) => lookup({ timeline: pairingTimeline({ steps, ...extra }), ...view });
afterEach(cleanup);

const searches = ['✓ Search by Album name and Artist: "Synthetic Live Album 2" · Synthetic Live Artist', '✓ Search by Album name only: "Synthetic Live Album 2"',
  '✓ Search by Album name and Artist: "Synthetic Live Album 2" · Synthetic Live Artist -Romanized-'];
const titles = '"Synthetic second song" · Synthetic Live Artist and "Synthetic opening" · Synthetic Live Artist';

test('while a run is active its steps read in order with what each searched, their states and counts, without a live region', () => {
  const { container } = show(running('2026-10-22T01:25:28.000Z'));
  expect(rows()).toEqual([...searches, `○ Search by track title: ${titles} (not started yet)`, '● Read release details (5 of 12 releases) (in progress)', '○ iTunes fallback (not started yet)',
    '○ Check the Albums iTunes returned on MusicBrainz (not started yet)', '○ Read Artist and label aliases (not started yet)']);
  expect(container.querySelector('[role="status"], [aria-live]')).toBeNull();
  // Open, not folded, and no record or names searched while it runs.
  expect(container.querySelector('details')).toBeNull();
  expect(screen.queryByText(/^This lookup searched/)).not.toBeInTheDocument();
});

test('a running run that shows no new step for more than five seconds of this page\'s clock says it waits for MusicBrainz, iTunes in the iTunes phase, and a queued or retrying run never does', () => {
  const now = Date.parse('2026-10-22T01:25:30.000Z');
  const element = (view: ReviewLookupView, at: number) => <MemoryRouter><LookupProgress lookup={view} now={at} albumHref={null} /></MemoryRouter>;
  // Its last step is already 12 seconds old by the server's clock, which this page does not trust: it counts from when it saw it.
  const view = running('2026-10-22T01:25:18.000Z'), { rerender } = render(element(view, now));
  expect(screen.queryByText(/^Waiting for/)).not.toBeInTheDocument();
  rerender(element(view, now + 5_000));
  expect(screen.queryByText(/^Waiting for/)).not.toBeInTheDocument();
  rerender(element(view, now + 12_000));
  expect(screen.getByText('Waiting for MusicBrainz (last progress 12 seconds ago)')).toBeInTheDocument();
  // A new step starts the count again, also one stamped ahead of this page's clock.
  const ahead = running('2026-10-22T01:25:52.000Z');
  rerender(element(ahead, now + 13_000));
  expect(screen.queryByText(/^Waiting for/)).not.toBeInTheDocument();
  rerender(element(ahead, now + 19_000));
  expect(screen.getByText('Waiting for MusicBrainz (last progress 6 seconds ago)')).toBeInTheDocument();
  cleanup();
  const itunes = running('2026-10-22T01:25:29.000Z', { progress: { phase: 'itunes', done: 0, total: 2, startedAt, updatedAt: '2026-10-22T01:25:29.000Z' } });
  render(element(itunes, now)).rerender(element(itunes, now + 6_000));
  expect(screen.getByText('Waiting for iTunes (last progress 6 seconds ago)')).toBeInTheDocument();
  cleanup();
  for (const other of [running('2026-10-22T01:25:00.000Z', { state: 'queued' }), running('2026-10-22T01:25:00.000Z', { state: 'retrying' })]) {
    render(element(other, now)).rerender(element(other, now + 60_000));
    expect(screen.queryByText(/^Waiting for/)).not.toBeInTheDocument();
    expect(rows()).toHaveLength(8);
    cleanup();
  }
});

test('after a run it says what it searched, then folds its steps under the record with the time taken, searches and releases', () => {
  const { container } = show(lookup());
  expect(screen.getByText('This lookup searched for "Synthetic Live Album 2" · Synthetic Live Artist, then "Synthetic Live Album 2" alone, '
    + 'then "Synthetic Live Album 2" · Synthetic Live Artist -Romanized-.')).toBeInTheDocument();
  const details = container.querySelector('details')!;
  expect(details.open).toBe(false);
  expect(within(details).getByText('Lookup log: took 22 s · 7 searches · 12 releases found').tagName).toBe('SUMMARY');
  expect(rows()).toEqual([...searches, `✓ Search by track title: ${titles}`, '✓ Read release details (12 of 12 releases)', '✓ iTunes fallback (2 of 2 searches)',
    '✓ Check the Albums iTunes returned on MusicBrainz (4 of 4 checks), found "Synthetic other Album 1"', '✓ Read Artist and label aliases (4 of 4 lookups)']);
  // The bridge row says why a release of another title was found: it is what iTunes returned for the names searched.
  expect(notes()).toEqual(['', '', '', '', '', '',
    '"Synthetic other Album 1" came back from iTunes as other Albums for the names searched, so their releases on MusicBrainz are among the releases found too.', '']);
  // The searched line comes before the record; without an end time the record counts to the last step.
  expect(container.firstElementChild!.tagName).toBe('P');
  cleanup();
  show(lookup({ timeline: pairingTimeline({ completedAt: null, updatedAt: '2026-10-22T01:26:01.000Z', steps: pairingTimeline().steps.slice(1, 2), trackTitleSearch: undefined }),
    candidates: pairingLookupResponse().lookup!.candidates.slice(0, 1) }));
  expect(screen.getByText('Lookup log: took 1 min 9 s · 1 search · 1 release found')).toBeInTheDocument();
  expect(screen.getByText('This lookup searched for "Synthetic Live Album 2".')).toBeInTheDocument();
});

test('a stopped run folds its record without the names searched, and the steps it never reached read as not run', () => {
  const stopped = pairingRunningTimeline('2026-10-22T01:25:10.000Z');
  const { container } = show(lookup({ state: 'stopped', issue: 'grantExpired', timeline: stopped }));
  expect(screen.queryByText(/^This lookup searched/)).not.toBeInTheDocument();
  expect(container.querySelector('details summary')!.textContent).toBe('Lookup log: took 18 s · 3 searches · 12 releases found');
  expect(rows().slice(3)).toEqual([`○ Search by track title: ${titles} (not run)`, '● Read release details (5 of 12 releases) (in progress)', '○ iTunes fallback (not run)',
    '○ Check the Albums iTunes returned on MusicBrainz (not run)', '○ Read Artist and label aliases (not run)']);
});

test('a search the run may not have sent reads as such, and is neither named as searched nor counted', () => {
  const steps = pairingTimeline().steps, titles = steps[3].texts!;
  show(lookup({ timeline: pairingTimeline({ steps: [steps[0], { ...steps[1], state: 'unconfirmed' }, { ...steps[2], state: 'unconfirmed' }, { ...steps[3], texts: titles.slice(0, 1) },
    { kind: 'trackTitle', state: 'unconfirmed', texts: titles.slice(1) }, ...steps.slice(4)] }) }));
  expect(rows().slice(0, 5)).toEqual([searches[0], '○ Search by Album name only: "Synthetic Live Album 2" (may not have been sent)',
    '○ Search by Album name and Artist: "Synthetic Live Album 2" · Synthetic Live Artist -Romanized- (may not have been sent)',
    '✓ Search by track title: "Synthetic second song" · Synthetic Live Artist', '○ Search by track title: "Synthetic opening" · Synthetic Live Artist (may not have been sent)']);
  expect(screen.getByText('This lookup searched for "Synthetic Live Album 2" · Synthetic Live Artist.')).toBeInTheDocument();
  // The first title search, the Track title sent for certain and the iTunes fallback's two searches.
  expect(screen.getByText('Lookup log: took 22 s · 4 searches · 12 releases found')).toBeInTheDocument();
});

test('a run that completed after MusicBrainz\'s retries ran out names no search, as it may not have sent them', () => {
  for (const issue of ['sourceUnavailable', 'sourceBusy'] as const) {
    show(lookup({ issue }));
    expect(screen.queryByText(/^This lookup searched/)).not.toBeInTheDocument();
    expect(screen.getByText(/^Lookup log:/)).toBeInTheDocument();
    cleanup();
  }
});

test('each Track-title state reads in its own words: sent with its titles, not needed, not yet, and every skip reason', () => {
  const row = (state: Timeline['steps'][number]['state'], search: Timeline['trackTitleSearch'], texts: Timeline['steps'][number]['texts'] | null = pairingTimeline().steps[3].texts) => {
    show(only([{ kind: 'trackTitle', state, ...(texts ? { texts } : {}) }], { trackTitleSearch: search }));
    const [text] = rows(); cleanup(); return text;
  };
  expect(row('done', { state: 'sent' })).toBe(`✓ Search by track title: ${titles}`);
  expect(row('done', { state: 'sent' }, null)).toBe('✓ Search by track title');
  expect(row('skipped', { state: 'notNeeded' }, null)).toBe('– Search by track title: not needed (the name searches found a matching release)');
  expect(row('pending', { state: 'pending' })).toBe(`○ Search by track title: ${titles} (not run)`);
  expect([row('skipped', { state: 'skipped', reason: 'positionsStart' }, null), row('skipped', { state: 'skipped', reason: 'fileName' }, null),
    row('skipped', { state: 'skipped', reason: 'generic' }, null), row('skipped', { state: 'skipped', reason: 'noneDistinct' }, null),
    row('skipped', { state: 'skipped', reason: 'unavailable' }, null)]).toEqual([
    '– Search by track title: skipped (the titles start with a track number, like file names)', '– Search by track title: skipped (the titles equal or look like their file names)',
    '– Search by track title: skipped (the titles are generic, such as Intro, only numbers or instrumental versions)',
    '– Search by track title: skipped (no title is distinctive enough to search)', '– Search by track title: not sent (MusicBrainz was unavailable)']);
});

test('the iTunes fallback reads as not needed or unavailable, or says only some of its results were compared, and the bridge names the titles it checked and why they were found; a search the candidate bound kept unsent is skipped', () => {
  show(only([{ kind: 'itunes', state: 'skipped' }], {}, { itunes: 'notQueried' }));
  expect(rows()).toEqual(['– iTunes fallback: not needed']);
  cleanup();
  show(only([{ kind: 'itunes', state: 'skipped' }, { kind: 'bridge', state: 'skipped' }, { kind: 'details', state: 'skipped' }], {}, { itunes: 'unavailable' }));
  expect(rows()).toEqual(['– iTunes fallback: iTunes was unavailable', '– Check the Albums iTunes returned on MusicBrainz (skipped)', '– Read release details (skipped)']);
  cleanup();
  show(only([{ kind: 'bridge', state: 'done', done: 2, total: 2, texts: [{ text: 'Synthetic other Album 1' }, { text: 'Synthetic other Album 2' }] },
    { kind: 'albumArtist', state: 'skipped', texts: [{ text: 'Synthetic Live Album 2', artist: 'Synthetic Live Artist -Romanized-' }] }]));
  expect(rows()).toEqual(['✓ Check the Albums iTunes returned on MusicBrainz (2 of 2 checks), found "Synthetic other Album 1" and "Synthetic other Album 2"',
    '– Search by Album name and Artist: "Synthetic Live Album 2" · Synthetic Live Artist -Romanized- (skipped)']);
  expect(notes()[0]).toMatch(/^"Synthetic other Album 1" and "Synthetic other Album 2" came back from iTunes as other Albums for the names searched/);
  cleanup();
  // An iTunes fallback that left results out of the comparison says only some were compared; one that kept every result says nothing more.
  show(only([{ kind: 'itunes', state: 'done', done: 2, total: 2, partial: true }, { kind: 'itunes', state: 'done', done: 1, total: 1 }]));
  expect(rows()).toEqual(['✓ iTunes fallback (2 of 2 searches)', '✓ iTunes fallback (1 of 1 search)']);
  expect(notes()).toEqual(['iTunes returned many Albums, so only the first 4 were checked on MusicBrainz.', '']);
  cleanup();
  // Every count names what it counts, also a bridge that found no title a shown release carries.
  show(only([{ kind: 'details', state: 'done', done: 1, total: 1 }, { kind: 'bridge', state: 'pending', done: 1, total: 3 }, { kind: 'aliases', state: 'done', done: 1, total: 1 }]));
  expect(rows()).toEqual(['✓ Read release details (1 of 1 release)', '○ Check the Albums iTunes returned on MusicBrainz (1 of 3 checks) (not run)',
    '✓ Read Artist and label aliases (1 of 1 lookup)']);
});

test('a search whose text is not shown reads as a search by name, and a song search names its song', () => {
  show(only([{ kind: 'albumArtist', state: 'done' }, { kind: 'song', state: 'done', texts: [{ text: 'Synthetic opening' }] },
    { kind: 'songArtist', state: 'done', texts: [{ text: 'Synthetic opening', artist: 'Synthetic Live Artist' }] }]));
  expect(rows()).toEqual(['✓ Search by name', '✓ Search by song name only: "Synthetic opening"', '✓ Search by song name and Artist: "Synthetic opening" · Synthetic Live Artist']);
  // Only searches with a shown text are named as searched.
  expect(screen.getByText('This lookup searched for "Synthetic opening", then "Synthetic opening" · Synthetic Live Artist.')).toBeInTheDocument();
});

test('a run ended because its Album changed offers opening the Album, with or without a timeline', () => {
  const ended = lookup({ state: 'superseded', issue: 'projectClosed' });
  show(ended, undefined, '/admin/catalog/album/0000000000000000000000a1');
  const link = screen.getByRole('link', { name: 'Open the Album to start a new completion' });
  expect(link).toHaveAttribute('href', '/admin/catalog/album/0000000000000000000000a1');
  expect(screen.getByText(/^Lookup log:/)).toBeInTheDocument();
  cleanup();
  show({ ...ended, timeline: undefined }, undefined, '/admin/catalog/album/0000000000000000000000a1');
  expect(screen.getByRole('link', { name: 'Open the Album to start a new completion' })).toBeInTheDocument();
  expect(screen.queryByRole('list')).not.toBeInTheDocument();
});

test('a view without a timeline renders nothing', () => {
  const { container } = show({ ...lookup(), timeline: undefined });
  expect(container).toBeEmptyDOMElement();
});
